using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SmartCampusServicePortal.Data; namespace SmartCampusServicePortal.Controllers; public class AdminController(ApplicationDbContext db):Controller{public async Task<IActionResult> Index(string? status)=>View(await db.ServiceRequests.Where(x=>string.IsNullOrEmpty(status)||x.Status==status).ToListAsync()); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Update(int id,string status,string? remarks){var r=await db.ServiceRequests.FindAsync(id);if(r==null)return NotFound();r.Status=status;r.AdminRemarks=remarks;await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}}